["iconSource"] = -1,
["wagoID"] = "-p1NZLBsd",
["xOffset"] = 0,
["preferToUpdate"] = true,
["customText"] = "function()\n    if aura_env.counter == 2 then\n        return \"快找掩体\"\n    elseif aura_env.counter > 1 then\n        return \"注意冰墓\"\n    else\n        return \"注意分散\"\n    end\nend\n\n\n",
["yOffset"] = 0,
["anchorPoint"] = "CENTER",
["cooldownSwipe"] = true,
["url"] = "https://afdian.com/a/Rurutia",
["icon"] = true,
["triggers"] = {
