["GCDHistoryCastControl"] = {
["iconSource"] = -1,
["wagoID"] = "6tQApQqWO",
["parent"] = "GCDHistory 施法序列",
["adjustedMax"] = "",
["customText"] = "\n\n",
["yOffset"] = 0,
