["暗影魔回蓝法力通报"] = {
["outline"] = "OUTLINE",
["wagoID"] = "pic2tj79D",
["parent"] = "【牧师】暗影魔攻击回蓝统计",
["displayText"] = "%1.amount Mana\n",
["customText"] = "function()\n    return m\nend\n\n\n\n",
["yOffset"] = -30,
["anchorPoint"] = "CENTER",
["displayText_format_p_time_format"] = 0,
["customTextUpdate"] = "update",
["automaticWidth"] = "Auto",
["actions"] = {
["start"] = {
["do_loop"] = false,
["message_format_1.amount_format"] = "Number",
["b"] = 1,
["g"] = 0.69803923368454,
["message_format_1.amount_pad"] = false,
["do_glow"] = false,
["do_sound"] = false,
["do_custom"] = false,
["message_format_1.amount_decimal_precision"] = 0,
["message_type"] = "PRINT",
["r"] = 0,
["message_format_1.amount_pad_max"] = 8,
["message"] = "通过暗影魔获得 %1.amount 法力！",
["message_format_1.amount_pad_mode"] = "left",
["custom"] = "function Rapture:SPELL_ENERGIZE(timestamp, event, sourceGUID, sourceName, sourceFlags, destGUID, destName, destFlags, spellId, spellName, spellSchool, auraType, amount)\n    local pet = UnitName(\"pet\")\n    if sourceName == pet and spellId == 34650 then\n        m = m + amount\n    end\nend",
["message_format_1.amount_round_type"] = "ceil",
["do_message"] = false,
["glow_action"] = "show",
["sound"] = "Interface\\Addons\\WeakAuras\\PowerAurasMedia\\Sounds\\sonar.ogg",
["sound_channel"] = "Ambience",
},
["init"] = {
["custom"] = "local totalm =0\nlocal hitm =0\nlocal playerGUID = UnitGUID(\"player\")\nlocal MSG_CRITICAL_HIT = \"暗影魔 %s %s hit %d Mana 累计%s。\"\nlocal MSG_CRITICAL_SUCCESS = \"已释放 %s 开始回蓝。\"\n\nlocal f = CreateFrame(\"Frame\")\nf:RegisterEvent(\"COMBAT_LOG_EVENT_UNFILTERED\")\nf:SetScript(\"OnEvent\", function(self, event)\n        self:COMBAT_LOG_EVENT_UNFILTERED(CombatLogGetCurrentEventInfo())\nend)\n\nfunction f:COMBAT_LOG_EVENT_UNFILTERED(...)\n    local timestamp, subevent, _, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags = ...\n    local spellId, spellName, spellSchool\n    local amount, overkill, school, resisted, blocked, absorbed, critical, glancing, crushing, isOffHand\n    \n    if subevent == \"SPELL_CAST_SUCCESS\" then\n        spellId, spellName, spellSchool = select(12, ...)\n    elseif subevent == \"SPELL_ENERGIZE\" then\n        spellId, spellName, spellSchool, amount, overkill, school, resisted, blocked, absorbed, critical, glancing, crushing, isOffHand = select(12, ...)\n    end\n    \n    if sourceGUID == playerGUID and spellId == 34433 then\n        local actionSUCCESS = spellId and GetSpellLink(spellId)\n        hiti=0\n        totalm = 0\n        hitm = 0\n        print(MSG_CRITICAL_SUCCESS:format(actionSUCCESS))\n    end\n    \n    if destGUID == playerGUID and spellId == 34650 then\n        local actionm = spellId and GetSpellLink(spellId)\n        totalm = totalm+ amount\n        hitm = hitm + 1\n        print(MSG_CRITICAL_HIT:format(actionm, hitm, amount, totalm))\n    end\nend",
["do_custom"] = false,
},
["finish"] = {
["message_format_1.amount_decimal_precision"] = 0,
["message_custom"] = "function()\n    return m\nend\n\n\n\n",
