["value"] = "function()\n    -- 定义需要检查的 Spell ID 列表\n    local targetSpells = {\n        [33702] = true, -- 血性狂怒 (AP)\n        [26297] = true, -- 狂暴\n        [33697] = true, -- 血性狂怒 (SP)\n        [20599] = true, -- 石像形态\n        --[48168] = true  -- 心灵之火、测试\n    }\n    \n    -- 遍历列表，检查玩家身上是否有任意一个指定 ID 的光环\n    for spellId, _ in pairs(targetSpells) do\n        if WA_GetUnitAura(\"player\", spellId) then\n            return true\n        end\n    end\n    return false \nend",
},
