["init"] = {
["do_custom_load"] = false,
["custom"] = "local e = aura_env\nlocal region = WeakAuras.GetRegion(e.id)\n\nif not _G[e.id..\"Button\"] then \n    e.btn = CreateFrame(\"Button\", e.id..\"Button\", region) \n    e.btn:RegisterForClicks(\"LeftButtonUp\", \"RightButtonUp\")\n    e.btn:SetAllPoints(region)\nend\n\nlocal btn = _G[e.id..\"Button\"]\n\nbtn:SetScript(\"OnClick\", function(self, button)\n        if button == \"LeftButton\" or button == \"RightButton\" then\n            if not MacroFrame then LoadAddOn(\"Blizzard_MacroUI\") end\n            if MacroFrame and MacroFrame:IsShown() then\n                HideUIPanel(MacroFrame)\n            else\n                ShowMacroFrame()\n            end\n        end\nend)\n\nbtn:SetScript(\"OnEnter\", function(self) region:SetScale(1.15) end)\nbtn:SetScript(\"OnLeave\", function(self) region:SetScale(1) end)\nbtn:SetScript(\"OnMouseDown\", function(self) region:SetAlpha(0.5) end)\nbtn:SetScript(\"OnMouseUp\", function(self) region:SetAlpha(1) end)\n\nbtn:Show()",
